def compress(s):
    result = ""
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        result += s[i] + str(j - i)
        i = j
    return result

def is_anagram(a, b):
    norm = lambda s: sorted(s.replace(" ", "").lower())
    return norm(a) == norm(b)

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append("FizzBuzz")
        elif i % 3 == 0:
            out.append("Fizz")
        elif i % 5 == 0:
            out.append("Buzz")
        else:
            out.append(str(i))
    return out

def flatten(items):
    out = []
    for x in items:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def group_by_letter(words):
    groups = {}
    for w in words:
        groups.setdefault(w[0], []).append(w)
    return groups

def top_customer(orders):
    totals = {}
    for o in orders:
        totals[o["user"]] = totals.get(o["user"], 0) + o["amount"]
    return max(totals, key=totals.get)

def digital_root(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def unique_in_order(s):
    out = []
    for ch in s:
        if not out or out[-1] != ch:
            out.append(ch)
    return out

def count_by_category(menu):
    counts = {}
    for dish in menu:
        counts[dish["category"]] = counts.get(dish["category"], 0) + 1
    return counts

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def is_square(self):
        return self.width == self.height

def strength(password):
    if len(password) < 8:
        return "слабый"
    has_digit = any(c.isdigit() for c in password)
    has_upper = any(c.isupper() for c in password)
    return "сильный" if has_digit and has_upper else "средний"

def is_balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
